create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table if not exists instruments(id uuid primary key default gen_random_uuid(), symbol text not null unique, exchange text not null, name text not null, instrument_type text not null default 'equity', active boolean not null default true, created_at timestamptz not null default now());
create table if not exists market_data(id uuid primary key default gen_random_uuid(), instrument_id uuid not null references instruments(id) on delete cascade, price numeric not null, change_pct numeric, volume bigint, source text not null, is_demo boolean not null default false, observed_at timestamptz not null default now());
create table if not exists candles(id uuid primary key default gen_random_uuid(), instrument_id uuid not null references instruments(id) on delete cascade, timeframe text not null, ts timestamptz not null, open numeric not null, high numeric not null, low numeric not null, close numeric not null, volume bigint not null, unique(instrument_id,timeframe,ts));
create table if not exists technical_indicators(id uuid primary key default gen_random_uuid(), instrument_id uuid not null references instruments(id) on delete cascade, timeframe text not null, ts timestamptz not null, name text not null, value numeric, metadata jsonb not null default '{}'::jsonb, unique(instrument_id,timeframe,ts,name));
create table if not exists signals(id uuid primary key default gen_random_uuid(), instrument_id uuid not null references instruments(id) on delete cascade, direction text not null check(direction in ('bullish','bearish','neutral')), score numeric check(score between 0 and 100), reason jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create table if not exists watchlists(id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, name text not null, created_at timestamptz not null default now());
create table if not exists watchlist_items(watchlist_id uuid not null references watchlists(id) on delete cascade, instrument_id uuid not null references instruments(id) on delete cascade, created_at timestamptz not null default now(), primary key(watchlist_id,instrument_id));
create table if not exists predictions(id uuid primary key default gen_random_uuid(), instrument_id uuid not null references instruments(id) on delete cascade, horizon text not null, direction text, probability numeric check(probability between 0 and 1), model_name text, created_at timestamptz not null default now());
create table if not exists strategies(id uuid primary key default gen_random_uuid(), user_id uuid references users(id) on delete cascade, name text not null, config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists backtests(id uuid primary key default gen_random_uuid(), user_id uuid references users(id) on delete cascade, strategy_id uuid references strategies(id) on delete set null, config jsonb not null default '{}'::jsonb, metrics jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists ai_conversations(id uuid primary key default gen_random_uuid(), user_id uuid references users(id) on delete cascade, title text, created_at timestamptz not null default now());
create table if not exists ai_messages(id uuid primary key default gen_random_uuid(), conversation_id uuid not null references ai_conversations(id) on delete cascade, role text not null check(role in ('user','assistant','system','tool')), content text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists idx_candles_instrument_ts on candles(instrument_id,ts desc); create index if not exists idx_market_data_instrument_observed on market_data(instrument_id,observed_at desc); create index if not exists idx_signals_score on signals(score desc); create index if not exists idx_ai_messages_conversation_created on ai_messages(conversation_id,created_at);
